    "footer_contact_title": "Contact",
    "footer_copy": "&copy; 2026 Maurinsoft Technology Solutions. All rights reserved.",
    "sobre_hero_tag": "About Maurinsoft",
    "sobre_hero_title": "Over two decades transforming challenges into tangible technology",
    "sobre_hero_desc": "Maurinsoft is a Brazilian technology company focused on practical, accessible, and robust solutions. Born from a passion for software engineering and applied electronics, we develop enterprise platforms and prototype physical industrial, commercial, and biomedical equipment.",
    "sobre_bio_tag": "Technical Leadership",
    "sobre_bio_title": "Marcelo Maurin Martins",
    "sobre_bio_role": "Founder, Software Engineer & Biomedical Systems Researcher",
    "sobre_bio_p1": "Founder and lead developer of Maurinsoft, Marcelo holds a degree in Data Processing from FATEC Taquaritinga and is completing his degree in Biomedical Systems at FATEC Ribeirão Preto. This hybrid foundation grants the company a rare capability: engaging in deep technical depth both at high-level enterprise software and down to sensors, ICs, microcontrollers, and regulated medical hardware.",
    "sobre_bio_p2": "He brings over 20 years of hands-on experience designing and sustaining mission-critical information systems, engineering in high-performance native languages (C, C++, Free Pascal / Lazarus, Python), and architecting relational and cloud database solutions.",
    "sobre_bio_p3": "His dedication to the open-source community and cross-platform engineering is reflected in recognized projects such as the Cockpit Drone simulator, the MultiCNC digital fabrication suite, the MNote2 IDE, and the award-winning Doctor biomedical platform (Best Thesis Award 2025 at FATEC).",
    "sobre_sec_values_title": "What drives us every day",
    "sobre_mission_title": "Mission",
    "sobre_mission_desc": "Democratize advanced technology by delivering tailored equipment and rock-solid software that solve real-world problems for small businesses, communities, and public healthcare with peak efficiency and honest costs.",
    "sobre_vision_title": "Vision",
    "sobre_vision_desc": "Be recognized as a hub of excellence in electronic prototyping and software engineering in Brazil, proving that homegrown high-quality solutions can match and surpass imported technology in versatility and reliability.",
    "sobre_values_title": "Values",
    "sobre_values_desc": "Total technical transparency, respect for the client's investment, zero predatory recurring fees, user data autonomy, and an unyielding commitment to engineering excellence.",
    "sobre_hq_title": "Headquartered in Jardinópolis - SP, Serving Worldwide",
    "sobre_hq_desc": "Situated in the technological and industrial hub of greater Ribeirão Preto, Maurinsoft blends agile localized support with remote and on-site delivery capabilities for corporations, healthcare networks, clinics, and academic institutions across the country and abroad.",
    "sobre_cta_title": "Ready to Build Your Next Engineering Project?",
    "sobre_cta_desc": "Get in touch with our engineering team to discuss technical specifications, timelines, and the practical feasibility of your hardware or software.",
    "sobre_cta_btn1": "Talk to Engineering",
    "sobre_cta_btn2": "Explore Our Services",
    "serv_hero_tag": "Equipment Prototyping & Software Engineering",
    "serv_hero_title": "We Build the Equipment and Software Your Business Needs",
    "serv_hero_desc": "From circuit schematics, PCB design, and embedded firmware to 3D printed / CNC machined enclosures and web / desktop management systems. No predatory recurring fees, with absolute technical transparency.",
    "serv_hero_btn1": "Request Technical Quote",
    "serv_hero_btn2": "Explore the Stages",
    "serv_cycle_tag": "Engineering Methodology",
    "serv_cycle_title": "The Complete Prototyping Cycle",
    "serv_cycle_desc": "Our process is structured to mitigate risks, rapidly validate hypotheses, and ensure the final prototype is ready for field deployment or regulatory certification.",
    "serv_step1_num": "1",
    "serv_step1_title": "Conceptual Engineering & Requirements",
    "serv_step1_desc": "Customer requirements mapping, technical and financial feasibility study, regulatory standard definition (ABNT, ANVISA, NR-10/12), and detailed system architecture specification.",
    "serv_step2_num": "2",
    "serv_step2_title": "Electronic Design & Sensor Integration",
    "serv_step2_desc": "Schematic capture and printed circuit board (PCB) layout using professional EDA tools (KiCad). Microcontroller selection (ESP32, STM32, Arduino, Raspberry Pi), analog signal conditioning, and communication modules.",
    "serv_step3_num": "3",
    "serv_step3_title": "Embedded Firmware Development",
    "serv_step3_desc": "Bare-metal and RTOS programming (C/C++) for hard real-time control of actuators, stepper motors, servomotors, biometric scanners, touch displays (LCD, OLED, TFT), thermal sensors, and load cells.",
    "serv_step4_num": "4",
    "serv_step4_title": "Industrial Enclosure & Mechanical Design",
    "serv_step4_desc": "Parametric 3D modeling using MultiCAD and professional CAD tools. Optimization for 3D printing (FDM / SLA engineering polymers like PETG, ABS, and technical resins) or CNC routing and laser cutting in acrylic, aluminum, and sheet metal.",
    "serv_step5_num": "5",
    "serv_step5_title": "Management Software & API Integration",
    "serv_step5_desc": "Desktop or web applications for prototype management, real-time telemetry dashboards, and protocol integration via TCP/IP, MQTT, WebSockets, or serial USB (RS-232 / RS-485) backed by MySQL or SQLite.",
    "serv_step6_num": "6",
    "serv_step6_title": "Bench Testing & Validation",
    "serv_step6_desc": "Assembly, calibration, electrical and thermal stress testing, power consumption profiling, comprehensive technical reporting, and compliance support for EMC and electrical safety certification.",
    "serv_bio_tag": "Biomedical & Healthcare Devices",
    "serv_bio_title": "Clinical Engineering & Healthcare Prototyping",
    "serv_bio_desc": "Backed by an academic background in Biomedical Systems from FATEC Ribeirão Preto, Maurinsoft engineers laboratory and clinical device prototypes in compliance with ANVISA regulations and IEC 60601 medical safety standards.",
    "serv_bio_item1": "✔ Medical protocol integration and automated generation of digitally signed diagnostic reports",
    "serv_bio_item2": "✔ Telemedicine and teleconsultation platforms with end-to-end encrypted audio/video (WebRTC)",
    "serv_bio_item3": "✔ IoT monitoring devices for vaccine cold-chain and medical storage with real-time telemetry alerts",
    "serv_bio_item4": "✔ Computer Vision & R&D: Automated Red Blood Cell Counter and cytological imaging for clinical diagnosis assistance",
    "serv_bio_btn": "Discuss Biomedical Project",
    "serv_com_tag": "Retail Automation & POS",
    "serv_com_title": "Commercial Equipment & Retail Automation",
    "serv_com_desc": "We optimize checkout points and customer journeys through smart connected devices built into the daily workflow of supermarkets, pharmacies, warehouses, and department stores.",
    "serv_com_item1": "✔ Kiosks & Queue Management: Auto-cutter ticket dispensers, multimedia displays, and natural voice announcements",
    "serv_com_item2": "✔ Price Auditing Systems: Shelf-edge labels, store signage, and barcode printing on industrial thermal printers",
    "serv_com_item3": "✔ Scale & Scanner Integration: Automated weight capture and barcode decoding at POS checkouts",
    "serv_com_item4": "✔ Visual Management Dashboards: In-store smart TVs displaying sales targets and real-time wait times",
    "serv_com_btn": "Request Retail Solution",
    "serv_cta_title": "Let's turn your idea into a working reality",
