    "contato_faq_tag": "Technical FAQ",
    "contato_faq_title": "Frequently Asked Questions",
    "contato_faq_q1": "How does the equipment prototyping workflow work?",
    "contato_faq_a1": "We begin with a technical scoping meeting. Next, we build a benchtop proof-of-concept, layout the production-ready PCB, 3D model custom enclosures, and deliver a fully calibrated, tested unit complete with firmware and management software.",
    "contato_faq_q2": "Does Maurinsoft software require mandatory recurring subscription fees?",
    "contato_faq_a2": "We operate with flexible and honest licensing models. Solutions like Queue Management can be acquired via perpetual licenses with optional SLAs. Custom engineering deliverables belong entirely to you with zero predatory lock-in.",
    "contato_faq_q3": "Do you serve businesses and partners outside São Paulo and globally?",
    "contato_faq_a3": "Yes! Our software platforms are deployed digitally across Brazil and worldwide. For physical hardware, prototypes are shipped via insured couriers, backed by comprehensive remote video commissioning or on-site engineering dispatch upon request.",
    "mc_hero_badge": "OPEN-SOURCE DIGITAL FABRICATION SUITE",
