    "footer_copy": "&copy; 2026 Maurinsoft Soluciones en Tecnología. Todos los derechos reservados.",
    "sobre_hero_tag": "Sobre Maurinsoft",
    "sobre_hero_title": "Más de dos décadas transformando desafíos en tecnología tangible",
    "sobre_hero_desc": "Maurinsoft es una empresa brasileña de tecnología enfocada en soluciones prácticas, accesibles y robustas. Nacida de la pasión por la ingeniería de software y la electrónica aplicada, desarrollamos plataformas empresariales y prototipamos equipos físicos industriales, comerciales y biomédicos.",
    "sobre_bio_tag": "Liderazgo Técnico",
    "sobre_bio_title": "Marcelo Maurin Martins",
    "sobre_bio_role": "Fundador, Ingeniero de Software e Investigador en Sistemas Biomédicos",
    "sobre_bio_p1": "Fundador y líder de desarrollo de Maurinsoft, Marcelo es tecnólogo en Procesamiento de Datos por FATEC Taquaritinga y estudiante de Sistemas Biomédicos en FATEC Ribeirão Preto. Esta formación híbrida otorga una capacidad distintiva: dominar tanto el software corporativo de alto nivel como el nivel físico de sensores, microcontroladores y dispositivos médicos regulados.",
    "sobre_bio_p2": "Acumula más de 20 años de experiencia práctica en la concepción y mantenimiento de sistemas de información para misiones críticas, desarrollo en lenguajes nativos de alto rendimiento (C, C++, Free Pascal / Lazarus, Python) y arquitectura de bases de datos relacionales y en la nube.",
    "sobre_bio_p3": "Su compromiso con el software libre y el desarrollo multiplataforma se refleja en proyectos reconocidos como el simulador Cockpit Drone, la suite de fabricación digital MultiCNC, el entorno MNote2 y la galardonada plataforma Doctor (Mejor Tesis 2025 en FATEC).",
    "sobre_sec_values_title": "Lo que nos impulsa cada día",
    "sobre_mission_title": "Misión",
    "sobre_mission_desc": "Democratizar la alta tecnología, entregando equipos a medida y software robusto que resuelvan problemas reales de pequeñas empresas y salud pública con máxima eficiencia y costo justo.",
    "sobre_vision_title": "Visión",
    "sobre_vision_desc": "Ser reconocida como un centro de excelencia en prototipado electrónico e ingeniería de software en Brasil, demostrando que soluciones nacionales de alta calidad superan en versatilidad y confiabilidad a las tecnologías importadas.",
    "sobre_values_title": "Valores",
    "sobre_values_desc": "Transparencia técnica total, respeto a la inversión del cliente, ausencia de tarifas recurrentes abusivas, autonomía del usuario sobre sus datos y compromiso inquebrantable con la excelencia de ingeniería.",
    "sobre_hq_title": "Con sede en Jardinópolis - SP, Atendiendo a Todo Brasil y el Mundo",
    "sobre_hq_desc": "Ubicada en el polo tecnológico e industrial de la región de Ribeirão Preto, Maurinsoft combina atención ágil y entregas remotas y presenciales para empresas, hospitales, clínicas y universidades en todo el país.",
    "sobre_cta_title": "¿Listo para Desarrollar su Próximo Proyecto de Tecnología?",
    "sobre_cta_desc": "Póngase en contacto con nuestro equipo de ingeniería para debatir especificaciones técnicas, plazos y viabilidad práctica de su equipo o software.",
    "sobre_cta_btn1": "Hablar con Ingeniería",
    "sobre_cta_btn2": "Explorar Nuestros Servicios",
    "serv_hero_tag": "Prototipado de Equipos e Ingeniería de Software",
    "serv_hero_title": "Desarrollamos el Equipo y el Software que su Negocio Necesita",
    "serv_hero_desc": "Desde la concepción del circuito, diseño de PCB y firmware hasta el gabinete en impresión 3D / mecanizado CNC y sistemas web / desktop de control. Sin tarifas abusivas y con total transparencia técnica.",
    "serv_hero_btn1": "Solicitar Cotización Técnica",
    "serv_hero_btn2": "Conocer las Etapas",
    "serv_cycle_tag": "Metodología de Ingeniería",
    "serv_cycle_title": "El Ciclo Completo de Prototipado",
    "serv_cycle_desc": "Nuestro proceso está estructurado para mitigar riesgos, validar hipótesis rápidamente y garantizar que el prototipo final esté listo para uso en campo o certificación regulatoria.",
    "serv_step1_num": "1",
    "serv_step1_title": "Ingeniería Conceptual y Requisitos",
    "serv_step1_desc": "Levantamiento de necesidades, estudio de viabilidad técnica y económica, definición de normativas aplicables (ABNT, ANVISA, NR-10/12) y arquitectura detallada del sistema.",
    "serv_step2_num": "2",
    "serv_step2_title": "Diseño Electrónico y Sensores",
    "serv_step2_desc": "Esquemáticos y diseño de placas PCB en herramientas profesionales (KiCad). Selección de microcontroladores (ESP32, STM32, Arduino, Raspberry Pi), acondicionamiento de señales analógicas y módulos de comunicación.",
    "serv_step3_num": "3",
    "serv_step3_title": "Desarrollo de Firmware Embebido",
    "serv_step3_desc": "Programación bare-metal y RTOS (C/C++) para control en tiempo real de actuadores, motores paso a paso, servomotores, lectores biométricos, pantallas táctiles y sensores de precisión.",
    "serv_step4_num": "4",
    "serv_step4_title": "Diseño Industrial del Gabinete",
    "serv_step4_desc": "Modelado 3D paramétrico en MultiCAD. Optimización para impresión 3D (PETG, ABS, resinas técnicas) o mecanizado CNC y corte láser en acrílico, aluminio y chapa metálica.",
    "serv_step5_num": "5",
    "serv_step5_title": "Software de Gestión e Integración",
    "serv_step5_desc": "Desarrollo de aplicaciones de escritorio o web para control del prototipo, paneles de visualización, e integración TCP/IP, MQTT, WebSockets o puertos serie USB con MySQL o SQLite.",
    "serv_step6_num": "6",
    "serv_step6_title": "Pruebas de Banco y Homologación",
    "serv_step6_desc": "Montaje, calibración, pruebas de estrés térmico y eléctrico, mediciones de consumo, emisión de informes técnicos y acompañamiento en ensayos de compatibilidad electromagnética.",
    "serv_bio_tag": "Equipos Biomédicos y Salud",
    "serv_bio_title": "Ingeniería Clínica y Prototipado en Salud",
    "serv_bio_desc": "Con sólida formación en Sistemas Biomédicos en FATEC Ribeirão Preto, Maurinsoft diseña prototipos de equipos de laboratorio y clínicos en cumplimiento de las normativas de ANVISA y NBR IEC 60601.",
    "serv_bio_item1": "✔ Integración con protocolos médicos y generación automática de informes digitales firmados",
    "serv_bio_item2": "✔ Plataformas de telemedicina y teleconsulta con audio y vídeo encriptado de extremo a extremo (WebRTC)",
    "serv_bio_item3": "✔ Dispositivos IoT para monitorización térmica en cámaras de vacunas y medicamentos con alertas en tiempo real",
    "serv_bio_item4": "✔ Visión por Computadora e I+D: Contador de Hematíes y citología automatizada para apoyo al diagnóstico",
    "serv_bio_btn": "Conversar sobre Proyecto Biomédico",
    "serv_com_tag": "Automatización Comercial y POS",
    "serv_com_title": "Equipos y Automatización para el Comercio",
    "serv_com_desc": "Optimizamos el punto de venta y la experiencia del cliente con equipos inteligentes integrados a la rutina de supermercados, farmacias y comercios mayoristas.",
    "serv_com_item1": "✔ Tótems y Gestión de Filas: Dispensadores de turnos con corte automático, paneles multimedia y llamada por voz sintética",
    "serv_com_item2": "✔ Sistemas de Precios: Impresión de etiquetas de góndola, cartelería y códigos de barra en impresoras térmicas",
    "serv_com_item3": "✔ Integración con Básculas y Lectores: Captura automática de peso y códigos en el checkout",
    "serv_com_item4": "✔ Paneles de Gestión Visual: Pantallas en el local con metas de ventas y tiempos de espera en tiempo real",
    "serv_com_btn": "Solicitar Solución para Retail",
