    "contato_faq_a1": "Iniciamos con una reunión técnica para relevar requisitos. Luego montamos una prueba de concepto en banco, diseñamos la PCB definitiva, modelamos el gabinete 3D y entregamos el equipo calibrado con firmware y software.",
