    "contato_faq_tag": "FAQ Technique",
    "contato_faq_title": "Questions Fréquentes",
    "contato_faq_q1": "Comment se déroule le cycle de prototypage d'équipements ?",
    "contato_faq_a1": "Nous commençons par une revue d'exigences techniques. Puis nous assemblons une preuve de concept, routons la PCB définitive, modélisons le boîtier 3D et livrons un appareil étalonné avec son firmware et logiciel.",
    "contato_faq_q2": "Les logiciels de Maurinsoft exigent-ils un abonnement mensuel obligatoire ?",
    "contato_faq_a2": "Nos modèles sont flexibles et transparents. Des solutions comme le Système de Files sont disponibles en licence perpétuelle avec support optionnel. Vos développements sur mesure vous appartiennent sans verrouillage.",
    "contato_faq_q3": "Accompagnez-vous des clients en dehors de São Paulo et à l'international ?",
    "contato_faq_a3": "Oui ! Nos logiciels sont déployés numériquement dans le monde entier. Pour le matériel, nous expédions les prototypes avec assurance et assurons la mise en service à distance ou sur site.",
    "mc_hero_badge": "SUITE OPEN SOURCE DE FABRICATION NUMÉRIQUE",
    "mc_hero_title": "MultiCNC: De l'Idée à la Fabrication dans un Seul Écosystème",
    "mc_hero_desc": "Plateforme open source développée en Free Pascal et Lazarus pour Fraiseuses CNC, Laser, Impression 3D, Électronique et Simulation Physique. Conception conceptuelle, CAO paramétrique, FAO, génération de G-Code et pilotage machine.",
    "mc_btn_download_win": "Télécharger pour Windows (Setup)",
    "mc_btn_github": "Voir le Code sur GitHub",
    "mc_flow_tag": "Le Flux Intégré de Fabrication Numérique",
    "mc_flow_title": "Une idée, plusieurs processus, un seul environnement",
    "mc_flow_desc": "MultiCNC élimine le cloisonnement dans la fabrication numérique. Fini les outils disparates et les formats incompatibles : la suite réunit des applications qui communiquent de l'ébauche jusqu'à l'usinage.",
    "mc_flow_hint": "💡 Conseil : Cliquez sur une étape ci-dessus pour ouvrir la fiche technique interactive avec photos, spécifications et manuels.",
