    "prod_doctor_title": "Doctor • Biomedizinische Automation",
    "prod_doctor_sub": "Beste Abschlussarbeit 2025 • Hard- und Software",
    "footer_desc": "Software-Engineering spezialisiert auf Geräte-Prototyping, biomedizinische Systeme und unternehmenskritische Industrieautomation.",
    "footer_products_title": "Produkte",
    "footer_links_title": "Schnelllinks",
    "footer_contact_title": "Kontakt",
    "footer_copy": "&copy; 2026 Maurinsoft Technologielösungen. Alle Rechte vorbehalten.",
    "sobre_hero_tag": "Über Maurinsoft",
    "sobre_hero_title": "Über zwei Jahrzehnte Verwandlung von Herausforderungen in greifbare Technologie",
    "sobre_hero_desc": "Maurinsoft ist ein brasilianisches Technologieunternehmen, das sich auf praktische, zugängliche und robuste Lösungen konzentriert. Aus Leidenschaft für Softwareentwicklung und angewandte Elektronik entwickeln wir Unternehmensplattformen und fertigen Prototypen für Industrie, Handel und Medizintechnik.",
    "sobre_bio_tag": "Technische Führung",
    "sobre_bio_title": "Marcelo Maurin Martins",
    "sobre_bio_role": "Gründer, Software-Ingenieur & Forscher für Biomedizinische Systeme",
    "sobre_bio_p1": "Als Gründer und Chefentwickler von Maurinsoft verfügt Marcelo über einen Abschluss in Datenverarbeitung (FATEC Taquaritinga) und studiert Biomedizinische Systeme (FATEC Ribeirão Preto). Diese Doppelkompetenz verbindet High-Level Unternehmenssoftware nahtlos mit Sensorik, Mikrocontrollern und Medizingeräten.",
    "sobre_bio_p2": "Er verfügt über mehr als 20 Jahre Praxiserfahrung in der Konzeption missionskritischer Systeme, der Entwicklung in performanten nativen Sprachen (C, C++, Free Pascal / Lazarus, Python) sowie relationalen und Cloud-Datenbankarchitekturen.",
    "sobre_bio_p3": "Sein Engagement für Open-Source spiegelt sich in renommierten Projekten wider: dem Cockpit Drone Simulator, der MultiCNC-Fertigungssuite, der MNote2-IDE und der preisgekrönten Biomedizinplattform Doctor (Beste Abschlussarbeit 2025 an der FATEC).",
    "sobre_sec_values_title": "Was uns jeden Tag antreibt",
    "sobre_mission_title": "Mission",
    "sobre_mission_desc": "Demokratisierung von Spitzentechnologie durch maßgeschneiderte Geräte und hochstabile Software, die reale Probleme von Unternehmen und dem Gesundheitswesen effizient und fair lösen.",
    "sobre_vision_title": "Vision",
    "sobre_vision_desc": "Als Exzellenzzentrum für Elektronik-Prototyping und Software-Engineering in Brasilien anerkannt zu werden und zu beweisen, dass heimische Qualitätslösungen importierte Technologien in Zuverlässigkeit übertreffen.",
    "sobre_values_title": "Werte",
    "sobre_values_desc": "Vollständige technische Transparenz, Respekt vor Kundeninvestitionen, Verzicht auf unfaire Abos, Datenhoheit des Nutzers und kompromissloses Bekenntnis zu handwerklicher Ingenieurpräzision.",
    "sobre_hq_title": "Hauptsitz in Jardinópolis - SP, Weltweit und National Tätig",
    "sobre_hq_desc": "Im Technologiezentrum der Metropolregion Ribeirão Preto verbindet Maurinsoft schnelle regionale Betreuung mit weltweiter Bereitstellungskompetenz für Industrie, Kliniken und Forschungszentren.",
    "sobre_cta_title": "Bereit für Ihr nächstes Technologieprojekt?",
    "sobre_cta_desc": "Kontaktieren Sie unser Ingenieurteam, um Spezifikationen, Zeitpläne und die Machbarkeit Ihrer Hard- oder Software zu besprechen.",
    "sobre_cta_btn1": "Ingenieure kontaktieren",
    "sobre_cta_btn2": "Unsere Dienstleistungen",
    "serv_hero_tag": "Geräte-Prototyping & Software-Engineering",
    "serv_hero_title": "Wir entwickeln die Hardware und Software, die Ihr Unternehmen braucht",
    "serv_hero_desc": "Vom Schaltplan, PCB-Design und Firmware bis hin zu 3D-Druck-/CNC-Gehäusen und Web-/Desktop-Steuersystemen. Ohne Knebel-Abos und mit vollständiger technischer Transparenz.",
    "serv_hero_btn1": "Technisches Angebot anfordern",
    "serv_hero_btn2": "Die Phasen kennenlernen",
    "serv_cycle_tag": "Ingenieur-Methodik",
    "serv_cycle_title": "Der komplette Prototyping-Zyklus",
    "serv_cycle_desc": "Unser Prozess minimiert Risiken, validiert Hypothesen zügig und stellt sicher, dass der Prototyp reif für den Praxiseinsatz oder die Zertifizierung ist.",
    "serv_step1_num": "1",
    "serv_step1_title": "Konzept-Engineering & Anforderungen",
    "serv_step1_desc": "Anforderungsanalyse, Machbarkeitsstudie, regulatorische Definition (Normen, CE, Medizin) und Ausarbeitung der detaillierten Systemarchitektur.",
    "serv_step2_num": "2",
    "serv_step2_title": "Elektronikdesign & Sensoren",
    "serv_step2_desc": "Schaltplanerstellung und PCB-Layout mit professionellen EDA-Werkzeugen (KiCad). Auswahl von Mikrocontrollern (ESP32, STM32, ARM), Signalaufbereitung und Funkmodule.",
    "serv_step3_num": "3",
    "serv_step3_title": "Firmware-Entwicklung (Embedded)",
    "serv_step3_desc": "Bare-Metal- und RTOS-Programmierung (C/C++) für harte Echtzeitsteuerung von Schrittmotoren, Servos, Sensoren, Wägezellen und Touch-Displays.",
    "serv_step4_num": "4",
    "serv_step4_title": "Gehäusedesign & Mechanische Konstruktion",
    "serv_step4_desc": "Parametrische 3D-Konstruktion in MultiCAD. Fertigungsoptimiert für 3D-Druck (PETG, ABS, technische Harze) oder CNC-Fräsen/Laserschneiden in Aluminium, Acryl und Blech.",
    "serv_step5_num": "5",
    "serv_step5_title": "Steuerungssoftware & Schnittstellen",
    "serv_step5_desc": "Desktop- oder Webanwendungen zur Prototypensteuerung, Echtzeit-Telemetrie-Dashboards und Schnittstellenanbindung über TCP/IP, MQTT, WebSockets oder serielle Busse mit SQL-Datenbanken.",
    "serv_step6_num": "6",
    "serv_step6_title": "Prüfstandstests & Zulassung",
    "serv_step6_desc": "Montage, Kalibrierung, thermische und elektrische Stresstests, Leistungsmessung, Erstellung technischer Prüfberichte und Begleitung bei EMV- und Sicherheitsprüfungen.",
    "serv_bio_tag": "Biomedizinische & Gesundheitssysteme",
    "serv_bio_title": "Klinische Technik & Prototypenbau für das Gesundheitswesen",
    "serv_bio_desc": "Gestützt auf fundiertes Know-how in biomedizinischen Systemen der renommierten FATEC Ribeirão Preto entwickelt Maurinsoft Prototypen für Labor- und Medizingeräte nach strengen IEC 60601-Standards.",
    "serv_bio_item1": "✔ Integration medizinischer Protokolle und automatisierte Erstellung digital signierter Befundberichte",
    "serv_bio_item2": "✔ Telemedizin- und Fernberatungsplattformen mit durchgängig verschlüsseltem Audio/Video (WebRTC)",
    "serv_bio_item3": "✔ IoT-Überwachungsgeräte für die Kühlkette von Impfstoffen und Arzneimitteln mit Echtzeit-Alarmierung",
    "serv_bio_item4": "✔ Computer Vision & F&E: Automatisierter Erythrozyten-Zähler und Zytologie-Bildanalyse zur Labor-Diagnostik",
    "serv_bio_btn": "Biomedizin-Projekt besprechen",
    "serv_com_tag": "Handelsautomation & POS-Systeme",
    "serv_com_title": "Geräte und Automation für den Einzelhandel",
    "serv_com_desc": "Wir optimieren den Checkout und das Kundenerlebnis durch intelligente Geräte für Supermärkte, Apotheken, Lager und Großhändler.",
    "serv_com_item1": "✔ Kiosksysteme & Warteschlangen: Ticketdrucker mit automatischem Schnitt, Multimedia-Anzeigen und Sprachsynthese",
    "serv_com_item2": "✔ Preisauszeichnung: Regalkanten-Etiketten, Werbeplakate und Barcodedruck auf Thermodruckern",
    "serv_com_item3": "✔ Waagen- & Scanner-Anbindung: Automatische Gewichtserfassung und Barcode-Dekodierung an der Kasse",
    "serv_com_item4": "✔ Visual Management Dashboards: Live-Monitore für Verkaufsziele und Wartezeiten direkt am Einsatzort",
    "serv_com_btn": "Einzelhandelslösung anfragen",
    "serv_cta_title": "Bringen wir Ihre Idee vom Papier in die Realität",
    "serv_cta_desc": "Wir arbeiten eng mit Ihrem technischen Team zusammen. Kontaktieren Sie uns für eine unverbindliche ingenieurtechnische Machbarkeitsanalyse.",
    "serv_cta_btn1": "Ingenieurangebot anfordern",
