    "contato_faq_tag": "Technische FAQ",
    "contato_faq_title": "Häufig gestellte Fragen",
    "contato_faq_q1": "Wie läuft der Prozess des Hardware-Prototypings ab?",
    "contato_faq_a1": "Wir starten mit einem technischen Scoping. Anschließend bauen wir einen Proof-of-Concept, routen die endgültige Platine (PCB), konstruieren das 3D-Gehäuse und liefern das geprüfte Gerät inklusive Firmware und Software aus.",
    "contato_faq_q2": "Verlangt Maurinsoft zwingend monatliche Abogebühren?",
    "contato_faq_a2": "Wir setzen auf faire und transparente Lizenzmodelle. Lösungen wie das Warteschlangen-System können per Einmallizenz erworben werden. Individuelle Entwicklungen gehören zu 100% Ihnen ohne Lock-in.",
    "contato_faq_q3": "Betreuen Sie Kunden außerhalb von São Paulo und weltweit?",
    "contato_faq_a3": "Ja! Unsere Softwarelösungen werden weltweit digital bereitgestellt. Hardware-Prototypen versenden wir versichert und unterstützen die Inbetriebnahme per Fernzugriff oder vor Ort.",
    "mc_hero_badge": "OPEN-SOURCE-SUITE FÜR DIGITALE FERTIGUNG",
