    "footer_desc": "Инженерия программного обеспечения: прототипирование оборудования, биомедицинские системы и промышленная автоматизация критически важных процессов.",
    "footer_products_title": "Продукты",
    "footer_links_title": "Быстрые ссылки",
    "footer_contact_title": "Контакты",
    "footer_copy": "&copy; 2026 Maurinsoft Технологические Решения. Все права защищены.",
    "sobre_hero_tag": "О компании Maurinsoft",
    "sobre_hero_title": "Более двух десятилетий превращения сложных вызовов в осязаемые технологии",
    "sobre_hero_desc": "Maurinsoft — бразильская технологическая компания, создающая практичные, надежные и доступные решения. Объединяя страсть к программной инженерии и прикладной электронике, мы разрабатываем корпоративные платформы и прототипируем промышленное, коммерческое и биомедицинское оборудование.",
    "sobre_bio_tag": "Техническое руководство",
    "sobre_bio_title": "Марсело Маурин Мартинс",
    "sobre_bio_role": "Основатель, инженер-программист и исследователь биомедицинских систем",
    "sobre_bio_p1": "Основатель и ведущий разработчик Maurinsoft Марсело имеет диплом по обработке данных (FATEC Taquaritinga) и специализируется на биомедицинских системах (FATEC Ribeirão Preto). Этот редкий симбиоз знаний позволяет проектировать как масштабируемое корпоративное ПО, так и физические электронные схемы, датчики и медицинские приборы.",
    "sobre_bio_p2": "Обладает более чем 20-летним практическим опытом создания и сопровождения критически важных систем, разработки на высокопроизводительных нативных языках (C, C++, Free Pascal / Lazarus, Python) и проектирования баз данных.",
    "sobre_bio_p3": "Его приверженность сообществу свободного ПО выражается в таких проектах, как симулятор Cockpit Drone, производственная сюита MultiCNC, среда разработки MNote2 и удостоенная награды биомедицинская платформа Doctor (Лучший дипломный проект 2025 года FATEC).",
    "sobre_sec_values_title": "Что движет нами каждый день",
    "sobre_mission_title": "Миссия",
    "sobre_mission_desc": "Демократизировать высокие технологии, создавая специализированное оборудование и надежный софт для решения насущных задач бизнеса и здравоохранения с максимальной эффективностью и честной ценой.",
    "sobre_vision_title": "Видение",
    "sobre_vision_desc": "Быть признанным центром передового опыта в области создания электронных прототипов и разработки ПО в Бразилии, доказывая, что отечественные технологии превосходят импортные аналоги по надежности и гибкости.",
    "sobre_values_title": "Ценности",
    "sobre_values_desc": "Полная техническая прозрачность, уважение к инвестициям клиентов, отказ от навязанных подписок, абсолютный контроль пользователя над данными и бескомпромиссная инженерная точность.",
    "sobre_hq_title": "Штаб-квартира в Жардинополисе (Сан-Паулу), работаем по всей Бразилии и миру",
    "sobre_hq_desc": "Расположенная в технологическом кластере Рибейран-Прету, Maurinsoft сочетает оперативность персонального взаимодействия с возможностью масштабного удаленного внедрения для предприятий, клиник и университетов.",
    "sobre_cta_title": "Готовы воплотить ваш следующий технологический проект?",
    "sobre_cta_desc": "Свяжитесь с нашей инженерной командой для обсуждения технических требований, сроков и практической реализуемости вашего оборудования или ПО.",
    "sobre_cta_btn1": "Связаться с инженерами",
    "sobre_cta_btn2": "Ознакомиться с услугами",
    "serv_hero_tag": "Прототипирование оборудования и разработка ПО",
    "serv_hero_title": "Разрабатываем оборудование и программное обеспечение для задач вашего бизнеса",
    "serv_hero_desc": "От схемотехники, проектирования печатных плат и прошивки микроконтроллеров до корпусов на 3D-принтерах/ЧПУ и управляющего веб/десктопного ПО. Без скрытых платежей и с полной технической ясностью.",
    "serv_hero_btn1": "Запросить технический расчет",
