    "serv_cycle_tag": "Инженерная методология",
    "serv_cycle_title": "Полный цикл прототипирования",
    "serv_cycle_desc": "Наш процесс построен так, чтобы снизить проектные риски, быстро проверить гипотезы и подготовить финальный прототип к промышленной эксплуатации или сертификации.",
    "serv_step1_num": "1",
    "serv_step1_title": "Концептуальное проектирование и требования",
    "serv_step1_desc": "Формализация требований, технико-экономическое обоснование, определение стандартов соответствия и составление детального технического задания архитектуры.",
    "serv_step2_num": "2",
    "serv_step2_title": "Схемотехника и интеграция датчиков",
    "serv_step2_desc": "Разработка принципиальных схем и трассировка многослойных печатных плат (KiCad). Выбор микроконтроллеров (ESP32, STM32, ARM), аналоговая фильтрация и интерфейсы связи.",
    "serv_step3_num": "3",
    "serv_step3_title": "Разработка встраиваемого микроПО (Firmware)",
    "serv_step3_desc": "Низкоуровневое программирование bare-metal и RTOS (C/C++) для жесткого реального времени: шаговые приводы, сервомоторы, сенсорные экраны, датчики силы и тензометрия.",
    "serv_step4_num": "4",
    "serv_step4_title": "Промышленный дизайн и конструирование корпуса",
    "serv_step4_desc": "Параметрическое 3D-моделирование в MultiCAD. Оптимизация под аддитивное производство (PETG, ABS, фотополимеры) либо ЧПУ-фрезерование и лазерный раскрой алюминия, стали и пластиков.",
    "serv_step5_num": "5",
    "serv_step5_title": "Управляющее ПО и интеграция систем",
    "serv_step5_desc": "Разработка управляющего десктопного или веб-приложения, мониторинговых дашбордов и протоколов обмена TCP/IP, MQTT, WebSockets, RS-485/USB с базами данных MySQL или SQLite.",
    "serv_step6_num": "6",
    "serv_step6_title": "Стендовые испытания и сертификация",
    "serv_step6_desc": "Сборка, калибровка, термо-электрические стресс-тесты, снятие энергетических профилей, составление официальных протоколов испытаний и подготовка к сертификации по ЭМС.",
    "serv_bio_tag": "Биомедицинские приборы и здравоохранение",
    "serv_bio_title": "Клиническая инженерия и прототипирование для медицины",
    "serv_bio_desc": "Опираясь на академическую подготовку в области биомедицинских систем FATEC Ribeirão Preto, Maurinsoft проектирует прототипы клинических и лабораторных приборов в соответствии со стандартами ГОСТ Р МЭК 60601 и международными нормами.",
    "serv_bio_item1": "✔ Интеграция с медицинскими протоколами и автоматическая генерация электронных заключений с цифровой подписью",
    "serv_bio_item2": "✔ Платформы телемедицины с надежным сквозным шифрованием аудио и видеопотоков (WebRTC)",
    "serv_bio_item3": "✔ IoT-устройства непрерывного контроля температуры холодильных камер вакцин и медикаментов с мгновенным оповещением",
    "serv_bio_item4": "✔ Компьютерное зрение и НИОКР: автоматический подсчет эритроцитов и цитологический анализ для клинической лаборатории",
    "serv_bio_btn": "Обсудить медицинский проект",
    "serv_com_tag": "Автоматизация торговли и кассовые узлы",
    "serv_com_title": "Оборудование и автоматизация для торговых сетей",
    "serv_com_desc": "Мы оптимизируем кассовую зону и клиентский опыт с помощью умных приборов, интегрированных в работу супермаркетов, аптек и распределительных центров.",
    "serv_com_item1": "✔ Сенсорные терминалы электронной очереди: чекопечатающие автоматы с автоотрезом, инфопанели и голосовой вызов",
    "serv_com_item2": "✔ Системы ценников: печать полочных этикеток, ценников и штрих-кодов на промышленных термопринтерах",
    "serv_com_item3": "✔ Интеграция весов и сканеров: автоматический весовой учет и быстрое считывание кодов на кассе",
    "serv_com_item4": "✔ Дашборды визуального менеджмента: ТВ-экраны в торговом зале с показателями продаж и временем ожидания",
    "serv_com_btn": "Запросить решение для торговли",
    "serv_cta_title": "Воплотим вашу концепцию в работающее устройство",
    "serv_cta_desc": "Мы работаем в тесном партнерстве с вашей инженерной командой. Свяжитесь с нами для экспертной оценки технической осуществимости проекта.",
