    "contato_faq_title": "Часто задаваемые вопросы",
    "contato_faq_q1": "Как устроен процесс прототипирования оборудования?",
    "contato_faq_a1": "Мы начинаем со сбора технических требований, затем собираем стендовый макет (PoC), трассируем серийную печатную плату (PCB), проектируем 3D-корпус и поставляем протестированный калиброванный прибор с прошивкой и ПО.",
    "contato_faq_q2": "Требуют ли программы Maurinsoft обязательной ежемесячной подписки?",
    "contato_faq_a2": "Мы придерживаемся честной ценовой политики. Такие решения, как электронная очередь, доступны по бессрочной лицензии. Все индивидуальные заказные разработки полностью принадлежат заказчику без привязки к вендору.",
    "contato_faq_q3": "Работаете ли вы с заказчиками за пределами Сан-Паулу и по всему миру?",
    "contato_faq_a3": "Да! Программные комплексы развертываются удаленно по всему миру. Физические приборы доставляются застрахованными транспортными компаниями с дистанционной или очной пусконаладкой.",
    "mc_hero_badge": "ОТКРЫТАЯ СЮИТА ЦИФРОВОГО ПРОИЗВОДСТВА",
    "mc_hero_title": "MultiCNC: От идеи до готового изделия в единой экосистеме",
    "mc_hero_desc": "Интегрированная открытая платформа на Free Pascal и Lazarus для ЧПУ-фрезеров, лазеров, 3D-печати, электроники и физмоделирования. Концептуальный проект, параметрический CAD, CAM, G-код и контроль станка.",
    "mc_btn_download_win": "Скачать для Windows (Установщик)",
    "mc_btn_github": "Исходный код на GitHub",
    "mc_flow_tag": "Интегрированный рабочий процесс цифрового производства",
