    "footer_desc": "专注于设备原型开发、生物医学系统和关键任务工业自动化的软件工程服务商。",
    "footer_products_title": "产品中心",
    "footer_links_title": "快速链接",
    "footer_contact_title": "联系我们",
    "footer_copy": "&copy; 2026 Maurinsoft 科技解决方案。保留所有权利。",
    "sobre_hero_tag": "关于 Maurinsoft",
    "sobre_hero_title": "二十余载砥砺前行，将复杂挑战化为扎实可靠的技术实体",
    "sobre_hero_desc": "Maurinsoft 是一家专注于实用、高性价比与高可靠性解决方案的巴西科技企业。凭借对软件工程和应用电子学的执着追求，我们开发企业级管理平台，并提供工业、商业和生物医学设备的物理原型制造。",
    "sobre_bio_tag": "技术领航",
    "sobre_bio_title": "Marcelo Maurin Martins",
    "sobre_bio_role": "创始人、主任软件工程师兼生物医学系统研究员",
    "sobre_bio_p1": "作为 Maurinsoft 创始人兼首席开发者，Marcelo 拥有 FATEC 数据处理学位，并在 FATEC Ribeirão Preto 深造生物医学系统。这种软硬件兼修的深厚底蕴赋予了公司独特的优势：既能架构复杂的企业级分布式系统，又能精通底层传感器、微控制器与医疗硬件设备。",
    "sobre_bio_p2": "拥有超过20年的关键任务系统架构与维护实战经验，精通高性能原生编译语言（C、C++、Free Pascal / Lazarus、Python）以及关系型数据库和云架构设计。",
    "sobre_bio_p3": "他对开源和跨平台技术的热情体现在一系列重量级项目中：Cockpit Drone 无人机多维仿真器、MultiCNC 数字化制造全套套件、MNote2 智能IDE以及荣获 FATEC 2025年度最佳毕业设计大奖的 Doctor 生物医学自动化平台。",
    "sobre_sec_values_title": "引领我们前行的核心价值观",
    "sobre_mission_title": "使命",
    "sobre_mission_desc": "让高新技术普惠大众：打造量身定制的高可靠性硬件与软件系统，以最高效能和合理成本解决企业、社会及公共医疗领域的真实痛点。",
    "sobre_vision_title": "愿景",
    "sobre_vision_desc": "成为卓越的硬件原型与软件工程创新高地，用事实证明自主研发的高品质技术在灵活性、耐用性与安全性上均能超越进口产品。",
    "sobre_values_title": "价值观",
    "sobre_values_desc": "恪守技术透明与诚信，珍视客户的每一分投入，拒绝捆绑霸王条款与隐性收费，赋予用户完全的数据自主权，追求精益求精的工程品质。",
    "sobre_hq_title": "总部位于巴西雅尔迪诺波利斯（圣保罗州），业务辐射全国与海外",
    "sobre_hq_desc": "坐落于圣保罗州里贝朗普雷图都市圈的工业与科技园区，Maurinsoft 兼具高效响应与成熟的远程/实地交付能力，服务于各大企事业单位、综合医院、专科诊所及高等学府。",
    "sobre_cta_title": "准备好开启您的下一个高科技工程项目了吗？",
    "sobre_cta_desc": "欢迎与我们的资深工程师团队深入交流，探讨技术规格、交付周期以及设备与软件的可行性方案。",
    "sobre_cta_btn1": "预约工程团队咨询",
    "sobre_cta_btn2": "查看工程与服务",
    "serv_hero_tag": "设备物理原型设计与全栈软件工程",
    "serv_hero_title": "量身研发契合企业实际需求的尖端设备与软件系统",
    "serv_hero_desc": "涵盖电路原理图设计、PCB制板、底层嵌入式固件开发，到3D打印/CNC高精度加工机壳以及云端/桌面端交互软件系统。拒绝不合理订阅捆绑，技术全流程透明开放。",
    "serv_hero_btn1": "申请技术评估与报价",
    "serv_hero_btn2": "了解研发闭环阶段",
    "serv_cycle_tag": "工程研发全景闭环",
    "serv_cycle_title": "全生命周期软硬件协同原型开发",
    "serv_cycle_desc": "严谨科学的流程闭环旨在规避设计风险，敏捷验证技术假设，确保交付的物理原型完全符合实际工况并具备适航/医疗/行业认证合规性。",
    "serv_step1_num": "1",
    "serv_step1_title": "概念工程与技术指标定义",
    "serv_step1_desc": "深度梳理业务与工况需求，开展软硬件可行性与成本预算评估，明确行业合规标准（安规、电磁兼容、医疗准入），制定详尽的技术架构规范。",
    "serv_step2_num": "2",
    "serv_step2_title": "电子原理图设计与多传感器融合",
    "serv_step2_desc": "利用专业EDA工具（KiCad等）完成电路原理图绘制与高密度PCB布线，优选高可靠微控制器（ESP32、STM32、ARM核芯片），设计精密微弱模拟信号调理与抗干扰总线通信接口。",
    "serv_step3_num": "3",
    "serv_step3_title": "底层嵌入式固件工程",
    "serv_step3_desc": "基于裸机与实时操作系统（FreeRTOS/RT-Thread）编写高性能 C/C++ 固件，实现步进电机、高精度伺服、触摸液晶屏、热敏传感与称重测力单元的硬实时毫秒级闭环控制。",
    "serv_step4_num": "4",
    "serv_step4_title": "工业结构设计与机械外壳工程",
    "serv_step4_desc": "运用 MultiCAD 进行精密参数化三维实体建模。针对工程级3D打印（PETG、ABS、耐高温高韧光固化树脂）以及数控雕刻/激光切削（铝合金、亚克力、钣金折弯）开展可制造性设计（DFM）。",
    "serv_step5_num": "5",
    "serv_step5_title": "中控交互软件与数字化系统集成",
    "serv_step5_desc": "研发原生桌面端或现代化Web端中控管理软件，呈现高帧率数据看板，打通 TCP/IP、MQTT、WebSockets、Modbus 与工业串口（RS-232 / RS-485），无缝对接 MySQL/SQLite 事务级数据库。",
    "serv_step6_num": "6",
    "serv_step6_title": "台架严苛实测与合规准入测试",
    "serv_step6_desc": "样机装配调试、精密标定、电气与热应力耐久极限测试、功耗测试，输出完整工程检测报告，全程协助电磁兼容（EMC）与电气安全法规认证。",
    "serv_bio_tag": "高端生物医学与医疗健康装备",
    "serv_bio_title": "临床工程与生命科学医疗原型研发",
    "serv_bio_desc": "依托 FATEC Ribeirão Preto 深厚的生物医学工程学术底蕴，Maurinsoft 严格遵循医疗安全标准（IEC 60601系列与监管准则），自主研发实验室检测仪器与临床辅助设备物理原型。",
    "serv_bio_item1": "✔ 深度对接临床诊疗规程，自动生成具有可信电子签名的结构化数字检验报告",
    "serv_bio_item2": "✔ 具备端到端军事级加密音视频流媒体通信的远程医疗与远程会诊平台（WebRTC架构）",
    "serv_bio_item3": "✔ 用于疫苗冷链与敏感药品恒温仓储的智能物联网监测设备，异常温差秒级主动报警",
    "serv_bio_item4": "✔ 计算机视觉前沿科研：红细胞显微图像智能计数器与血液细胞学自动辅助诊断分析系统",
    "serv_bio_btn": "咨询生物医学项目",
    "serv_com_tag": "商业零售自动化与收银终端设备",
    "serv_com_title": "新零售智能商用硬件与自动化终端",
    "serv_com_desc": "深度赋能商超便利、医药连锁、大型仓储及批发零售业态，以工业级智能终端重构收银效率与前沿购物体验。",
    "serv_com_item1": "✔ 排队管理一体机：自动切纸取号机、高清晰度多媒体液晶屏与多语种真人语音叫号播报",
    "serv_com_item2": "✔ 货架精准标价系统：货架标签、促销POP海报及商品条码热敏打印与手持终端扫码联动",
    "serv_com_item3": "✔ 计重秤与扫码枪无缝通讯：收银台动态精准计重与高灵敏条形码/二维码秒级采集",
    "serv_com_item4": "✔ 门店可视化中控看板：商用电视实时轮播销售目标达成进度与排队等待时长监控",
    "serv_com_btn": "定制商业零售方案",
    "serv_cta_title": "让我们将您的宏伟构想落成为经得起实战检验的科技成果",
    "serv_cta_desc": "我们将作为值得信赖的工程技术外脑与您的团队紧密协作。欢迎联络我们，开启无偿技术可行性研讨与方案构想。",
