    "contato_faq_tag": "常见技术与商务问题解答",
    "contato_faq_title": "客户常见关切解答",
    "contato_faq_q1": "设备与硬件原型的完整研发周期是怎样的？",
    "contato_faq_a1": "首先进行深入的技术规格论证。随后搭建台架实验概念验证样机（PoC），完成工业级PCB精密布板，定制化建模并制造3D/CNC结构机壳，最后交付经严格校准、配备完整固件与上位机管理软件的成品机。",
    "contato_faq_q2": "Maurinsoft 的软件产品是否强制收取高额月度订阅费？",
    "contato_faq_a2": "我们坚信透明共赢的商业模式。标准系统（如排队管理）支持买断式终身授权与按需技术支持；定制化研发成果的知识产权与源代码完全归客户所有，绝无商业绑架。",
    "contato_faq_q3": "你们是否为圣保罗州以外乃至巴西境外的国际客户提供服务？",
    "contato_faq_a3": "毫无疑问！我们的纯软件平台支持面向全球范围的即时数字化交付。对于实体硬件设备，我们采用全保运输安全发运样机，并通过远程高精度调试或驻场工程师完成系统联调上线。",
    "mc_hero_badge": "开源数字化全流程智造套件",
    "mc_hero_title": "MultiCNC：从创意构想至实体制造的一体化智造生态",
    "mc_hero_desc": "基于 Free Pascal 和 Lazarus 构建的高性能开源集成制造套件，全面覆盖数控雕刻机、激光加工、3D打印、电子PCB与物理仿真。实现概念规划、参数化三维CAD、CAM切削、G代码生成与实时机床控制无缝流转。",
    "mc_btn_download_win": "下载 Windows 安装程序",
    "mc_btn_github": "在 GitHub 上查看源码",
