    "contato_faq_title": "よくあるご質問",
    "contato_faq_q1": "専用機器の試作プロセスはどのように進みますか？",
    "contato_faq_a1": "要件定義ミーティングから始まります。次にベンチトップでのPoC検証を実施し、量産対応のPCB設計、3D専用筐体の製作を経て、校正・実証試験済みの実機にファームウェアおよび管理ソフトウェアを付帯して納品します。",
    "contato_faq_q2": "Maurinsoftのソフトウェアは月額サブスクリプションが必須ですか？",
    "contato_faq_a2": "弊社は透明性の高い柔軟なライセンス体系を採用しています。順番待ち管理システム等は永久ライセンスでの導入が可能です。カスタム開発の成果物はお客様の資産となり、理不尽な囲い込みはありません。",
    "contato_faq_q3": "サンパウロ州外や海外の顧客・企業にも対応していますか？",
    "contato_faq_a3": "はい、ソフトウェアは全国および全世界へデジタル納品が可能です。物理機器は保険付き輸送で確実にお届けし、リモート接続またはオンサイトでの立ち上げ・設置支援をご提供いたします。",
    "mc_hero_badge": "オープンソース・デジタルファブリケーションスイート",
