    "sobre_hero_tag": "Maurinsoft के बारे में",
    "sobre_hero_title": "चुनौतियों को ठोस और व्यावहारिक तकनीक में बदलने के दो दशक से अधिक का अनुभव",
    "sobre_hero_desc": "Maurinsoft एक ब्राज़ीलियाई प्रौद्योगिकी कंपनी है जो व्यावहारिक, सुलभ और मजबूत समाधानों पर केंद्रित है। सॉफ्टवेयर इंजीनियरिंग और अनुप्रयुक्त इलेक्ट्रॉनिक्स के प्रति जुनून से जन्मी, हम एंटरप्राइज प्लेटफॉर्म और औद्योगिक, वाणिज्यिक व बायोमेडिकल उपकरणों के प्रोटोटाइप विकसित करते हैं।",
    "sobre_bio_tag": "तकनीकी नेतृत्व",
    "sobre_bio_title": "मार्सेलो मॉरिन मार्टिंस",
    "sobre_bio_role": "संस्थापक, सॉफ्टवेयर इंजीनियर और बायोमेडिकल सिस्टम शोधकर्ता",
    "sobre_bio_p1": "Maurinsoft के संस्थापक और प्रमुख डेवलपर, मार्सेलो FATEC से डेटा प्रोसेसिंग में स्नातक हैं और FATEC रिबेराओ प्रेटो से बायोमेडिकल सिस्टम का अध्ययन कर रहे हैं। यह दोहरा अनुभव कंपनी को उच्च-स्तरीय एंटरप्राइज सॉफ्टवेयर और सेंसर, माइक्रोकंट्रोलर व मेडिकल हार्डवेयर दोनों में असाधारण महारत प्रदान करता है।",
    "sobre_bio_p2": "उनके पास मिशन-महत्वपूर्ण सूचना प्रणालियों के निर्माण, उच्च-प्रदर्शन वाली नेटिव भाषाओं (C, C++, Free Pascal / Lazarus, Python) और रिलेशनल व क्लाउड डेटाबेस आर्किटेक्चर में 20 से अधिक वर्षों का व्यावहारिक अनुभव है।",
    "sobre_bio_p3": "ओपन-सोर्स समुदाय के प्रति उनका समर्पण कॉकपिट ड्रोन सिम्युलेटर, मल्टीसीएनसी डिजिटल फैब्रिकेशन सुइट, MNote2 आईडीई और 2025 FATEC बेस्ट थीसिस विजेता बायोमेडिकल प्लेटफॉर्म Doctor जैसे प्रसिद्ध प्रोजेक्ट्स में झलकता है।",
    "sobre_sec_values_title": "वह सिद्धांत जो हमें हर दिन प्रेरित करते हैं",
    "sobre_mission_title": "हमारा मिशन",
    "sobre_mission_desc": "उन्नत तकनीक को सभी के लिए सुलभ बनाना: कस्टम-निर्मित उपकरण और अत्यधिक स्थिर सॉफ्टवेयर प्रदान करना जो वास्तविक समस्याओं को पूरी दक्षता और उचित लागत पर हल करें।",
    "sobre_vision_title": "हमारा विजन",
    "sobre_vision_desc": "इलेक्ट्रॉनिक प्रोटोटाइपिंग और सॉफ्टवेयर इंजीनियरिंग में उत्कृष्टता के केंद्र के रूप में पहचाने जाना, यह साबित करते हुए कि स्वदेशी समाधान बहुमुखी प्रतिभा और विश्वसनीयता में सर्वश्रेष्ठ हैं।",
    "sobre_values_title": "मूल्य",
    "sobre_values_desc": "पूर्ण तकनीकी पारदर्शिता, ग्राहक के निवेश का सम्मान, अनुचित मासिक शुल्कों से मुक्ति, उपयोगकर्ता डेटा संप्रभुता, और अनुप्रयुक्त इंजीनियरिंग के प्रति अटूट प्रतिबद्धता।",
    "sobre_hq_title": "जार्डिनोपोलिस - एसपी में मुख्यालय, पूरे ब्राजील और अंतरराष्ट्रीय स्तर पर सेवा प्रदान करता है",
    "sobre_hq_desc": "रिबेराओ प्रेटो के तकनीकी और औद्योगिक केंद्र में स्थित, मॉरिनसॉफ्ट कंपनियों, अस्पतालों और विश्वविद्यालयों के लिए ऑन-साइट और रिमोट डिलीवरी क्षमताओं के साथ त्वरित सहायता प्रदान करता है।",
