    "serv_com_title": "वाणिज्य और खुदरा के लिए उपकरण और स्वचालन",
    "serv_com_desc": "हम सुपरमार्केट, फार्मेसी और गोदामों के दैनिक कार्यप्रवाह में एकीकृत स्मार्ट उपकरणों के माध्यम से पॉइंट ऑफ़ सेल और खरीदारी अनुभव को अनुकूलित करते हैं।",
    "serv_com_item1": "✔ कियोस्क और कतार प्रबंधन: स्वचालित कटर टिकट डिस्पेंसर, मल्टीमीडिया डिस्प्ले और वॉयस कॉल",
    "serv_com_item2": "✔ मूल्य निर्धारण प्रणाली: थर्मल प्रिंटर पर शेल्फ़-एज लेबल, पोस्टर और बारकोड प्रिंटिंग",
    "serv_com_item3": "✔ तराजू और स्कैनर एकीकरण: चेकआउट पर स्वचालित वजन कैप्चर और बारकोड डिकोडिंग",
    "serv_com_item4": "✔ विजुअल मैनेजमेंट डैशबोर्ड: बिक्री लक्ष्यों और प्रतीक्षा समय को प्रदर्शित करने वाले स्मार्ट डिस्प्ले",
