    "contato_faq_q1": "उपकरण प्रोटोटाइपिंग कार्यप्रवाह कैसे काम करता है?",
    "contato_faq_a1": "हम तकनीकी बैठक से शुरू करते हैं। फिर बेंचटॉप प्रूफ-ऑफ-कॉन्सेप्ट बनाते हैं, उत्पादन-तैयार पीसीबी डिजाइन करते हैं, 3 डी एनक्लोजर मॉडल करते हैं, और फर्मवेयर व सॉफ्टवेयर के साथ कैलिब्रेटेड उपकरण वितरित करते हैं।",
    "contato_faq_q2": "क्या मॉरिनसॉफ्ट सॉफ्टवेयर के लिए अनिवार्य मासिक सदस्यता शुल्क आवश्यक है?",
    "contato_faq_a2": "हम लचीले और पारदर्शी लाइसेंसिंग मॉडल पर काम करते हैं। कतार प्रबंधन जैसे समाधान स्थायी लाइसेंस के माध्यम से प्राप्त किए जा सकते हैं। कस्टम प्रोजेक्ट पूरी तरह से आपके हैं।",
    "contato_faq_q3": "क्या आप साओ पाउलो से बाहर और वैश्विक स्तर पर ग्राहकों को सेवा प्रदान करते हैं?",
    "contato_faq_a3": "हाँ! हमारे सॉफ्टवेयर उत्पाद डिजिटल रूप से विश्व स्तर पर वितरित किए जाते हैं। भौतिक उपकरणों के लिए, प्रोटोटाइप बीमाकृत कूरियर द्वारा भेजे जाते हैं और रिमोट या ऑन-साइट सहायता प्रदान की जाती है।",
